from q4_6 import Q, mc, tf, out, blank

# extra for 3 and 4
mc(3, "3.1", 1, "Which file wraps every view in the same header and footer?", ["_ViewStart.cshtml", "_Layout.cshtml", "_ViewImports.cshtml", "Index.cshtml"], 1, "@RenderBody() in _Layout marks where each view goes.")
blank(3, "3.1", 2, "In _Layout.cshtml, mark where each view's content goes.", "<main>\n    @____()\n</main>", ["RenderBody"], "RenderBody inserts the current view.")
mc(3, "3.1", 2, "_ViewImports.cshtml is for...", ["Layout HTML", "@using and @addTagHelper lines shared by all views", "CSS", "Routes"], 1, "Saves repeating the same usings in every view.")
blank(4, "4.2", 2, "Throw the domain's own exception when money runs out.", "throw new ____(balance, amount);", ["InsufficientFundsException"], "A custom exception carries the details (balance, requested amount).")
mc(4, "4.2", 2, "Why does the domain library (Banking.Domain) have no database or web code?", ["Size", "So the business rules can be tested and reused without infrastructure", "It's not allowed", "Speed"], 1, "The repository interface says WHAT it needs; other projects say HOW.")
tf(4, "4.1", 2, "A loose .dll reference (<Reference HintPath>) brings its dependencies along automatically.", False, "Only packages carry dependency information; that's why 4.1 says avoid loose dlls.")
mc(4, "4.1", 2, "Where does a .csproj put package metadata like the id and version?", ["In nuget.config", "In <PropertyGroup> (PackageId, Version)", "In Program.cs", "In appsettings.json"], 1, "dotnet pack reads them from the project file.")

# ---------------- Section 7: Security, Background Tasks & Deployment ----------------
S = 7
mc(S, "7.1", 1, "Authentication vs authorization:", ["Same thing", "Who are you? vs What may you do?", "Passwords vs cookies", "Login vs logout"], 1, "UseAuthentication must come before UseAuthorization.")
blank(S, "7.1", 1, "Only admins may call this action.", "[Authorize(____ = \"Admin\")]", ["Roles"], "Roles = \"Admin,Manager\" means EITHER role; stacking two [Authorize] means BOTH.")
mc(S, "7.1", 2, "[Authorize(Roles = \"Admin\")] when a logged-in non-admin calls it returns...", ["401", "403 Forbidden (cookie auth redirects to AccessDenied)", "404", "200"], 1, "401 means not logged in; 403 means logged in but not allowed.")
mc(S, "7.1", 2, "Two separate [Authorize(Roles = ...)] attributes on one action mean...", ["either role", "both roles required", "the last one wins", "compile error"], 1, "Each attribute must pass.")
mc(S, "7.2", 1, "XSS (cross-site scripting) is...", ["A database attack", "Injecting script that runs in other users' browsers", "A CSRF token", "A slow page"], 1, "Razor's @ encoding stops it; Html.Raw on user input brings it back.")
mc(S, "7.2", 2, "CSRF is stopped by...", ["HTTPS", "An antiforgery token in each form, checked on POST", "Encoding output", "CORS"], 1, "[ValidateAntiForgeryToken] / automatic in Razor forms.")
blank(S, "7.2", 2, "Check the antiforgery token on a POST action.", "[HttpPost]\n[____]\npublic IActionResult Save(EntryForm form)", ["ValidateAntiForgeryToken"], "Forms built with tag helpers include the token automatically.")
mc(S, "7.2", 3, "7.2's antiforgery cookie had SecurePolicy Always. Over plain HTTP the POST...", ["Worked", "Crashed: the cookie can't be sent without HTTPS", "Returned 400", "Was ignored"], 1, "The tests had to use HTTPS.")
tf(S, "7.2", 2, "A Content-Security-Policy header can block inline scripts even if XSS gets in.", True, "Defence in depth: encoding first, CSP second.")
mc(S, "7.3", 2, "Which base class runs a long-lived loop in the background of a web app?", ["Controller", "BackgroundService", "Middleware", "DbContext"], 1, "Override ExecuteAsync(stoppingToken); register with AddHostedService<T>().")
blank(S, "7.3", 2, "Register a background service.", "builder.Services.____<EmailSendingBackgroundService>();", ["AddHostedService"], "It starts with the app and is stopped on shutdown.")
mc(S, "7.3", 3, "A BackgroundService needs a scoped service (DbContext). It should...", ["Inject it in the constructor", "Create a scope with IServiceScopeFactory for each unit of work", "Make it a singleton", "Use new"], 1, "A singleton holding a scoped service is a captive dependency.")
mc(S, "7.3", 2, "PeriodicTimer vs Task.Delay in a loop:", ["Same", "PeriodicTimer ticks on a fixed schedule; Delay adds the work time to each gap", "Delay is more exact", "PeriodicTimer blocks a thread"], 1, "7.3's TimerStyle variation shows the drift.")
mc(S, "7.4", 2, "Output caching stores...", ["Database rows", "Whole HTTP responses on the server", "Browser cookies", "Static files only"], 1, "[OutputCache] / CacheOutput(); VaryByQuery for different query strings.")
blank(S, "7.4", 2, "Add a health check endpoint.", "app.____(\"/health\");", ["MapHealthChecks"], "Plus builder.Services.AddHealthChecks().")
mc(S, "7.4", 3, "ResponseCache vs OutputCache:", ["Same", "ResponseCache only sets headers for browsers/proxies; OutputCache stores responses on the server", "OutputCache is client-side", "ResponseCache stores in Redis"], 1, "7.4 compares them in its variations.")
mc(S, "7.5", 2, "A percentage rollout should use...", ["Random each request", "A stable hash of the user id, so a user stays in or out", "The time of day", "The IP address only"], 1, "Random flickers between requests (7.5's variation showed it).")
mc(S, "7.6", 1, "Where must GitHub Actions workflow files live?", ["/workflows", ".github/workflows/", "Projects/ci", "Anywhere"], 1, "GitHub only runs YAML files from .github/workflows/.")
mc(S, "7.6", 2, "concurrency: cancel-in-progress: true does what?", ["Runs jobs in parallel", "A newer push cancels the older, still-running run", "Retries failures", "Blocks pushes"], 1, "That's why this repo's history shows 'cancelled' runs that aren't failures.")
mc(S, "7.7", 2, "An idempotent migration script...", ["Runs once only", "Can be run again safely: each migration checks if it was already applied", "Deletes data", "Needs no database"], 1, "dotnet ef migrations script --idempotent wraps each in IF NOT EXISTS.")
blank(S, "7.7", 2, "Generate a script safe to run twice.", "dotnet ef migrations script ____", ["--idempotent"], "Ideal for deployment pipelines.")
mc(S, "7.7", 3, "Expand-then-contract for zero downtime means...", ["Drop the old column first", "Add new things first (both versions work), remove old things in a later release", "Shrink the database", "Take the site offline"], 1, "Old and new app versions run side by side during a deploy.")
mc(S, "7.7", 3, "Why wrap CREATE PROCEDURE in EXEC(N'...') inside the idempotent script?", ["Speed", "CREATE PROCEDURE must be first in a batch; it can't sit inside an IF block directly", "Security", "Required by SQLite"], 1, "7.7 hit this error.")
mc(S, "7.8", 2, "app.UseWebSockets() + context.WebSockets.AcceptWebSocketAsync() gives...", ["A REST API", "A two-way connection both sides can send on any time", "Server-sent events", "gRPC"], 1, "Raw frames; SignalR (8.8) builds on top with reconnects and groups.")
mc(S, "7.8", 3, "One ReceiveAsync call returns...", ["Always a whole message", "Part of a message: loop until EndOfMessage", "A whole connection", "A string"], 1, "Big messages arrive in several frames.")
mc(S, "7.9", 2, "IDistributedCache with Redis is for...", ["One server's memory", "A cache shared by every server instance", "The database", "Static files"], 1, "In-memory caches differ per server.")
mc(S, "7.9", 3, "After updating a price in the database, the cache should...", ["Do nothing", "Remove (or overwrite) the cached value", "Restart Redis", "Double the expiry"], 1, "No invalidation = stale prices until expiry (7.9's variation).")
tf(S, "7.9", 2, "IDistributedCache stores byte arrays (GetString/SetString are helpers on top).", True, "You serialize objects yourself, e.g. to JSON.")

# ---------------- Section 8: Beyond the Roadmap ----------------
S = 8
blank(S, "8.1", 1, "A minimal API GET endpoint.", "app.____(\"/books/{id:int}\", (int id) => ...);", ["MapGet"], "MapPost, MapPut, MapDelete for the others.")
mc(S, "8.1", 2, "Why return Results<Ok<Book>, NotFound> instead of IResult?", ["Speed", "OpenAPI can see both possible status codes", "Required", "IResult can't return 404"], 1, "With plain IResult the document loses the 404.")
mc(S, "8.1", 3, "A minimal API parameter bool uppercase with no default and no ?uppercase in the URL gives...", ["false", "400 Bad Request", "null", "true"], 1, "Non-nullable without a default = required. Use bool uppercase = false.")
mc(S, "8.1", 2, "Why use a DTO (SaveBookRequestModel) instead of binding the entity?", ["Faster", "Clients can't over-post fields like CostPrice, and secret fields don't leak in responses", "EF needs it", "Required by OpenAPI"], 1, "8.1's entity endpoint let a client set costPrice: -100.")
mc(S, "8.2", 2, "A JWT is...", ["An encrypted database", "A signed token carrying claims; the server checks the signature", "A cookie name", "A password hash"], 1, "Anyone can READ a JWT; only the key holder can SIGN one.")
blank(S, "8.2", 2, "Require a policy on an endpoint.", ".____(\"AdminOnly\");", ["RequireAuthorization"], "Policies are defined with AddAuthorizationBuilder().AddPolicy(...).")
mc(S, "8.2", 3, "ClockSkew in JWT validation is...", ["Token lifetime", "Extra time allowed after expiry (default 5 minutes)", "Server timezone", "Refresh interval"], 1, "Set to TimeSpan.Zero for tests that expect exact expiry.")
mc(S, "8.3", 2, "Why use IHttpClientFactory instead of new HttpClient() per call?", ["Shorter code", "Avoids socket exhaustion and DNS problems; adds named/typed clients", "Required by HTTPS", "Faster JSON"], 1, "It pools the underlying handlers.")
blank(S, "8.3", 2, "Add retries, timeouts and a circuit breaker in one call.", "builder.Services.AddHttpClient<RateClient>().____();", ["AddStandardResilienceHandler"], "From Microsoft.Extensions.Http.Resilience.")
mc(S, "8.3", 2, "A circuit breaker...", ["Retries forever", "Stops calling a failing service for a while, failing fast", "Encrypts calls", "Caches responses"], 1, "Gives the other service time to recover.")
mc(S, "8.4", 2, "A token bucket limiter...", ["Allows a fixed number per minute exactly", "Refills tokens over time and allows short bursts", "Limits concurrent requests only", "Blocks forever"], 1, "Fixed window, sliding window, token bucket and concurrency are the four built-ins.")
blank(S, "8.4", 2, "Apply a rate-limit policy to an endpoint.", ".____(\"fixed\");", ["RequireRateLimiting"], "Plus app.UseRateLimiter().")
mc(S, "8.4", 1, "Default status code when a request is rate-limited (ASP.NET Core)?", ["429", "503 unless you set RejectionStatusCode", "403", "500"], 1, "Set options.RejectionStatusCode = 429 to send Too Many Requests.")
mc(S, "8.5", 2, "Native AOT publishing breaks code that...", ["Uses async", "Relies on runtime reflection (e.g. reflection-based JSON)", "Uses LINQ", "Uses records"], 1, "Use source-generated JsonSerializerContext instead.")
mc(S, "8.5", 2, "Trimming removes...", ["Comments", "Code that looks unused, which can break reflection", "Whitespace", "Tests"], 1, "Mark risky code with [RequiresUnreferencedCode].")
mc(S, "8.5", 1, "dotnet publish --self-contained includes...", ["Only your dll", "The .NET runtime too, so the machine doesn't need .NET installed", "Source code", "Tests"], 1, "Bigger output, no install needed.")
mc(S, "8.6", 2, "In Razor Pages, the code for Contacts.cshtml lives in...", ["A controller", "Contacts.cshtml.cs, a PageModel class", "Program.cs", "_Layout"], 1, "OnGet / OnPost handlers instead of actions.")
blank(S, "8.6", 2, "Bind a property for POST in a PageModel.", "[____]\npublic ContactForm Form { get; set; } = new();", ["BindProperty"], "Add SupportsGet = true to bind on GET too.")
mc(S, "8.7", 2, "Blazor Server runs component code...", ["In the browser", "On the server, with UI updates over a SignalR connection", "In a worker", "At build time"], 1, "Blazor WebAssembly runs it in the browser instead (this repo's Playground).")
blank(S, "8.7", 2, "Two-way bind an input in Blazor.", "<input @____=\"todo.Title\" />", ["bind"], "@bind:event=\"oninput\" updates on every keystroke.")
mc(S, "8.7", 2, "EventCallback vs Action for a component parameter:", ["Same", "EventCallback re-renders the parent automatically and supports async", "Action is async", "EventCallback is slower"], 1, "Prefer EventCallback for child-to-parent events.")
mc(S, "8.8", 2, "A strongly typed SignalR hub (Hub<IChatClient>) prevents...", ["Reconnects", "Typos in client method names", "Groups", "Authentication"], 1, "With Clients.All.SendAsync(\"ReceiveMesage\") a typo just silently does nothing.")
mc(S, "8.8", 2, "Clients.Others sends to...", ["Everyone", "Everyone except the caller", "Only the caller", "A group"], 1, "Clients.Caller = only the sender; Clients.Group(name) = a group.")
mc(S, "8.9", 2, "gRPC defines its API in...", ["OpenAPI JSON", "A .proto file; code is generated for both sides", "C# attributes", "XML"], 1, "Field numbers in .proto must never be reused.")
mc(S, "8.9", 3, "A gRPC deadline that passes gives the client...", ["Timeout exception from HttpClient", "RpcException with StatusCode.DeadlineExceeded", "null", "An empty reply"], 1, "Deadlines travel to the server, which can stop early.")
tf(S, "8.9", 2, "gRPC needs HTTP/2.", True, "That's also why browsers need gRPC-Web.")

# ---------------- Section 9: Design Patterns & Architecture ----------------
S = 9
blank(S, "9.1", 2, "Overload + for Money.", "public static Money ____ +(Money left, Money right)", ["operator"], "Operators are public static methods named operator +, operator ==, ...")
mc(S, "9.1", 2, "Why is Money's conversion to decimal 'explicit' rather than 'implicit'?", ["Speed", "Converting loses the currency, so the caller must ask for it with a cast", "C# rule", "No reason"], 1, "Implicit conversions happen silently.")
mc(S, "9.1", 2, "Expression<Func<T, bool>> vs Func<T, bool>:", ["Same", "An Expression is code as data that can be read (e.g. turned into SQL) or compiled", "Func is slower", "Expression can't take parameters"], 1, "EF Core reads expressions to build SQL.")
mc(S, "9.1", 2, "Comparison<T> is used by...", ["List.ConvertAll", "List.Sort", "Where", "Select"], 1, "A Func<T, T, int> with the same body must be wrapped: new Comparison<T>(func).")
blank(S, "9.1", 3, "Declare a custom GENERIC delegate.", "public ____ TResult Transformer<T, TResult>(T input);", ["delegate"], "Same shape as Func<T, TResult>, but with its own name.")
mc(S, "9.2", 2, "Later configuration sources...", ["are ignored", "override earlier ones for the same key", "are merged by appending", "throw"], 1, "appsettings.json < appsettings.{Env}.json < environment variables < command line.")
mc(S, "9.2", 3, "A YAML list in a later file with FEWER items than an earlier file's list...", ["Replaces it", "Overwrites by index; extra old items stay", "Throws", "Is ignored"], 1, "Configuration merges lists by index (9.2 found this).")
mc(S, "9.3", 2, "A fluent builder returns ___ from each method so calls chain.", ["void", "this (or a new builder)", "null", "a string"], 1, "new OrderBuilder().ForCustomer(\"Ann\").AddLine(...).Build()")
mc(S, "9.3", 2, "'required' on a property means...", ["It can't be null at run time", "The object initializer must set it, or it doesn't compile", "It's validated on save", "It's a key"], 1, "C# 11. Together with init, it's set once at creation.")
mc(S, "9.4", 1, "The Strategy pattern...", ["Creates objects", "Swaps one algorithm for another behind the same interface", "Logs calls", "Caches results"], 1, "Shipping cost strategies: standard, express, free.")
mc(S, "9.4", 2, "The State pattern replaces...", ["Loops", "A big switch on status with one class per state that knows its allowed moves", "Inheritance", "Events"], 1, "pending -> paid -> shipped -> delivered.")
mc(S, "9.4", 2, "A mediator...", ["Connects to the database", "Lets senders send a request without knowing which handler handles it", "Is a logger", "Is a middleware"], 1, "mediator.Send(new PlaceOrderRequest(...)).")
mc(S, "9.4", 2, "The Command pattern is good for...", ["Sorting", "Undo/redo: each action is an object that can be executed and undone", "Caching", "Routing"], 1, "9.4's editor keeps a history of commands.")
mc(S, "9.5", 2, "Chain of responsibility:", ["Every handler runs", "Each handler handles the request or passes it to the next", "One handler only", "Handlers run in parallel"], 1, "Approval limits: team lead, manager, director.")
mc(S, "9.5", 2, "A decorator...", ["Changes the original class", "Wraps an object with the same interface to add behaviour (logging, caching)", "Is an attribute", "Is a subclass only"], 1, "Callers can't tell the difference.")
mc(S, "9.5", 3, "DispatchProxy is used for...", ["HTTP calls", "Intercepting every call on an interface at run time (AOP logging)", "Database access", "Threads"], 1, "Rethrow with ExceptionDispatchInfo to keep the original stack trace.")
mc(S, "9.6", 2, "In TPL Dataflow, a BatchBlock<T>(100)...", ["Runs 100 in parallel", "Groups items into arrays of 100", "Drops after 100", "Retries 100 times"], 1, "Then an ActionBlock saves each batch.")
blank(S, "9.6", 2, "Let completion flow from one block to the next.", "parse.LinkTo(save, new DataflowLinkOptions { ____ = true });", ["PropagateCompletion"], "Without it the last block never completes.")
mc(S, "9.7", 2, "Compensation in a workflow (saga) means...", ["Paying staff", "Undoing earlier steps when a later step fails", "Retrying forever", "Logging"], 1, "Refund the payment if shipping fails.")
mc(S, "9.8", 2, "Rx Throttle (debounce) vs Sample:", ["Same", "Throttle waits for a quiet period; Sample takes the latest every interval", "Sample waits for quiet", "Neither drops items"], 1, "9.8's price ticks show the difference.")
mc(S, "9.8", 2, "IObservable<T> vs IEnumerable<T>:", ["Same", "Observable PUSHES items to you; Enumerable lets you PULL them", "Enumerable is async", "Observable is a list"], 1, "Subscribe vs foreach.")
blank(S, "9.9", 1, "Register a service with one instance per request.", "builder.Services.____<IOrderService, OrderService>();", ["AddScoped"], "AddSingleton = one forever; AddTransient = new each time.")
mc(S, "9.9", 2, "GetService<T>() vs GetRequiredService<T>() when T isn't registered:", ["Both throw", "null vs InvalidOperationException", "Both null", "Both create it"], 1, "Required is the usual choice.")
mc(S, "9.9", 3, "A singleton that takes a scoped service in its constructor is called...", ["A factory", "A captive dependency", "A decorator", "A keyed service"], 1, "ValidateScopes/ValidateOnBuild catch it at startup.")
blank(S, "9.9", 2, "Register several IJob implementations without duplicates.", "services.____(ServiceDescriptor.Transient(typeof(IJob), jobType));", ["TryAddEnumerable"], "Adds only if that exact implementation isn't registered yet.")
mc(S, "9.9", 2, "Prefixes: Add... / Use... / Map... mean...", ["All the same", "register services / add middleware / add endpoints", "add endpoints / register / middleware", "Random"], 1, "AddControllers, UseRouting, MapGet.")
mc(S, "9.9", 3, "Reflection: PropertyInfo.SetValue on an 'init' property...", ["Throws", "Works: reflection skips the compiler's init rule", "Compile error", "Does nothing"], 1, "9.9's ReflectionVariation test proves it.")
mc(S, "9.9", 3, "An exception thrown inside a method called with MethodInfo.Invoke arrives as...", ["The same exception", "TargetInvocationException wrapping it", "ArgumentException", "Nothing"], 1, "Look at InnerException.")

# ---------------- Section 10: SaaS ----------------
S = 10
mc(S, "10.1", 1, "In a SaaS app, a tenant is...", ["A server", "One customer company using the app", "A database table", "A user role"], 1, "Many tenants share one app (and here, one database).")
mc(S, "10.1", 2, "A global query filter...", ["Speeds up queries", "Adds a WHERE to every query for that entity automatically", "Filters logs", "Validates input"], 1, "HasQueryFilter(p => p.TenantId == CurrentTenantId).")
blank(S, "10.1", 2, "Add the tenant filter.", "modelBuilder.Entity<ProjectModel>().____(project => project.TenantId == CurrentTenantId);", ["HasQueryFilter"], "Every query gets WHERE TenantId = ... without anyone writing it.")
mc(S, "10.1", 3, "Why must the filter read a PROPERTY of the DbContext, not a local variable from OnModelCreating?", ["Style", "The model is built once and cached; a local is baked in for the first tenant forever", "Speed", "EF can't read locals"], 1, "10.1's CapturedFilter variation: globex saw acme's rows.")
mc(S, "10.1", 2, "TenantContext is registered as...", ["Singleton", "Scoped (one per request)", "Transient", "Static"], 1, "A singleton would let requests overwrite each other's tenant.")
mc(S, "10.1", 2, "Acme asks for globex's project id. The API should return...", ["403", "404", "200 with the data", "500"], 1, "404 doesn't reveal that the id exists.")
tf(S, "10.1", 2, "FromSql($\"SELECT * FROM Projects\") is still filtered by the tenant query filter.", True, "EF wraps the raw query and adds the filter.")
tf(S, "10.1", 3, "Database.ExecuteSqlAsync(\"UPDATE Projects ...\") is filtered by the tenant query filter.", False, "Raw commands bypass the filter: add WHERE TenantId = {tenant} yourself.")
blank(S, "10.1", 2, "Admin-only: turn the filter off for one query.", "database.Projects.____().CountAsync();", ["IgnoreQueryFilters"], "Keep these rare and behind an admin policy.")
mc(S, "10.1", 3, "Why is the X-Tenant header alone unsafe in production?", ["Headers are slow", "The client chooses it; take the tenant from the signed token or check membership", "Headers can't hold text", "Browsers strip it"], 1, "Anyone could type 'globex'.")
mc(S, "10.1", 2, "When no tenant is set, the filter compares with \"\" so the query returns...", ["Everything", "Nothing (fail closed)", "An exception", "The first tenant"], 1, "A forgotten tenant sees nothing, not everyone's data.")
mc(S, "10.1", 2, "Database per tenant vs shared database with TenantId:", ["Same", "Per tenant: strongest isolation but N databases to migrate; shared: cheap but one bug can leak", "Shared is safer", "Per tenant is cheaper"], 1, "Many SaaS apps mix them.")
mc(S, "10.1", 3, "SaveChanges stamps TenantId on Added rows. What happens if code changes an existing row's TenantId?", ["It moves tenants", "SaveChanges throws", "Ignored", "Creates a copy"], 1, "Moving data between tenants is blocked.")
blank(S, "10.1", 2, "Read the tenant from the subdomain acme.myapp.com.", "string tenant = host.____('.')[0];", ["Split"], "10.1's FromHost also rejects www, the bare domain and nested subdomains.")
mc(S, "10.1", 2, "Scoped services in conventional middleware should be injected...", ["In the constructor", "As InvokeAsync parameters", "As static fields", "They can't be"], 1, "The middleware instance lives for the whole app.")
tf(S, "10.1", 2, "A tenantId sent in the JSON body is ignored because the request model has no such field.", True, "The client can't choose where data goes.")
mc(S, "10.1", 3, "Most important SaaS test?", ["Speed", "Tenant A can't read, change or delete tenant B's data", "UI colors", "Logging format"], 1, "A cross-tenant leak is the classic SaaS disaster.")
mc(S, "10.1", 2, "Indexing TenantId matters because...", ["It's required", "Every query filters on it", "It's a key", "EF needs it"], 1, "Without it, each request scans the whole table as tenants grow.")
tf(S, "10.1", 1, "Many tenants can share one app and one database.", True, "That's the shared model 10.1 uses.")
mc(S, "10.1", 2, "Which SaaS building block usually comes AFTER multi-tenancy?", ["Organizations, invites and per-tenant roles", "Changing fonts", "Removing tests", "Unit conversion"], 0, "Then plans/limits, billing webhooks, audit log, outbox, observability.")
blank(S, "10.1", 3, "Fill in the operator so a missing tenant becomes \"\".", "public string TenantId => Tenant?.Id ____ \"\";", ["??"], "Null-coalescing: a forgotten tenant matches no rows.")
mc(S, "10.1", 2, "The claim-based tenant source is safest because...", ["It's fastest", "Changing a signed token's claim breaks its signature", "Claims are encrypted", "Cookies can't change"], 1, "Header/subdomain/path are all chosen by the client.")
